={{ (() => {
const ctx = $('Montar contexto agente').first().json || {};
  const inb = ctx.inbound || {};
  const cat = ctx.catalog || {};
  const mem = ctx.customer_memory || {};
  const def = ctx.defaults || {};

  const now = new Date();
  const today = now.toISOString().slice(0, 10);
  const tomorrow = new Date(now.getTime() + 86400000).toISOString().slice(0, 10);
  const displayName =
    String(mem.registered_name || inb.push_name || inb.customer_name || '')
      .trim() || null;
  const firstName = displayName ? displayName.split(/\s+/)[0] : null;

  const servicesList = (cat.services || [])
    .map((s) => `${s.name} (id: ${s.id})`)
    .join('; ');
  const prosList = (cat.professionals || [])
    .map((p) => `${p.name} (id: ${p.id})`)
    .join('; ');

  const lastAppt = mem.last_appointment;
  const lastApptLine = lastAppt
    ? `${lastAppt.service_name || 'servico'} com ${lastAppt.professional_name || 'profissional'} em ${lastAppt.starts_at || '?'} (status: ${lastAppt.status || '?'})`
    : '(sem historico de agendamento no cadastro)';

  const nextAppt = mem.next_appointment;
  const nextApptLine = nextAppt
    ? `${nextAppt.service_name || 'servico'} em ${nextAppt.starts_at || '?'}`
    : '(nenhum agendamento futuro)';

  const recentSvc = (mem.recent_services || [])
    .map((r) => `${r.name} (ultima vez: ${r.last_at || '?'})`)
    .join('; ');

  const draft = inb.scheduling_draft || {};
  const draftLine =
    draft && Object.keys(draft).length
      ? JSON.stringify(draft)
      : '(vazio — colete na conversa)';

  return [
    '=== CONTEXTO ===',
    'Data referencia hoje: ' + today,
    'Data referencia amanha: ' + tomorrow,
    'Nome cadastrado: ' + String(mem.registered_name || 'nao informado'),
    'Nome WhatsApp (push_name): ' + String(inb.push_name || 'desconhecido'),
    'Primeiro nome para tratamento: ' + String(firstName || 'pergunte com gentileza'),
    'Cliente VIP: ' + (mem.is_vip ? 'sim' : 'nao'),
    'Telefone: ' + String(inb.phone || ''),
    'customer_id: ' + String(inb.customer_id || def.customer_id || ''),
    '',
    '=== MEMORIA DO CLIENTE (relembre com naturalidade — nao seja invasiva) ===',
    'Ultimo agendamento relevante: ' + lastApptLine,
    'Proximo agendamento: ' + nextApptLine,
    'Servicos ja realizados (historico): ' + (recentSvc || '(nenhum concluido)'),
    'Rascunho parcial desta conversa (nao repita perguntas): ' + draftLine,
    '',
    '=== CONVERSA (multi-turn — leia TUDO; aprenda tom e preferencias) ===',
    'Ultima mensagem do cliente: ' + String(inb.message || ''),
    'Historico completo:',
    String(inb.session_text || inb.message || ''),
    '',
    '=== CATALOGO (ofereca opcoes — NAO escolha sozinho) ===',
    'Servicos: ' + (servicesList || '(catalogo indisponivel)'),
    'Profissionais: ' + (prosList || '(catalogo indisponivel)'),
    '',
    '=== ATENDIMENTO HUMANIZADO ===',
    '1) Saudacao ou "quero agendar" sem detalhes: cumprimente pelo nome, opcionalmente cite o ultimo atendimento, pergunte servico + profissional + dia/horario. intent=coletar_agendamento, ready_to_book=false.',
    '2) Uma pergunta por vez. Tom gentil; espelhe a educacao do cliente.',
    '3) Com servico+profissional+data+horario: resuma e peca confirmacao. ready_to_book=false.',
    '4) Apos sim/confirmo: intent=criar_agendamento, ready_to_book=true.',
    '5) Sugestao extra (max 1 frase): ex. outro servico do catalogo ou "quer manter o mesmo profissional da ultima vez?" — so se couber; nunca empurre venda.',
    '',
    'Retorne JSON: intent, ready_to_book, professional_id, service_id, appointment_date, appointment_time, customer_id, response_text.',
  ].join('\n');
})() }}

parameters.jsCode:
const root = $input.first().json ?? {};
const parent = $('Preparar contexto inbound').first().json ?? {};
const inbound = parent.inbound ?? {};
let catalog = { services: [], professionals: [] };
let defaults = {};
try {
  const ctx = $('Montar contexto agente').first().json ?? {};
  catalog = ctx.catalog ?? catalog;
  defaults = ctx.defaults ?? {};
} catch (_) {
  /* legado */
}

const UUID_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const okUuid = (v) => typeof v === 'string' && UUID_RE.test(v.trim());

const sessionText = String(inbound.session_text ?? inbound.message ?? '').trim();
const lastMessage = String(inbound.message ?? '').trim();

function parseAgentPayload(raw) {
  if (raw == null) return {};
  let v = raw;
  if (typeof v === 'string') {
    const s = v.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '');
    try {
      v = JSON.parse(s);
    } catch (_) {
      return {};
    }
  }
  if (v && typeof v === 'object' && typeof v.output === 'string') {
    return parseAgentPayload(v.output);
  }
  return v && typeof v === 'object' ? v : {};
}

function resolveFromCatalog(value, list, nameKeys = ['name', 'title']) {
  if (okUuid(value)) return value.trim();
  const q = String(value ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
  if (!q) return null;
  for (const item of list) {
    const id = item.id;
    if (!okUuid(id)) continue;
    for (const k of nameKeys) {
      const n = String(item[k] ?? '')
        .toLowerCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '');
      if (!n) continue;
      if (n.includes(q) || q.includes(n)) return id;
    }
  }
  return null;
}

function todayIsoDate() {
  return new Date().toISOString().slice(0, 10);
}

function tomorrowIsoDate() {
  const d = new Date();
  d.setUTCDate(d.getUTCDate() + 1);
  return d.toISOString().slice(0, 10);
}

function isIsoDate(value) {
  return /^\d{4}-\d{2}-\d{2}$/.test(String(value ?? ''));
}

function resolveAppointmentDate(rawDate, sessionText) {
  if (/amanha|amanhã/i.test(sessionText)) {
    return tomorrowIsoDate();
  }
  const candidate = rawDate ?? null;
  if (!isIsoDate(candidate)) return null;
  if (candidate < todayIsoDate()) return null;
  return candidate;
}

function parseTimeHint(text) {
  const m = String(text).match(/\b(\d{1,2})\s*[:h]\s*(\d{2})\b/i);
  if (!m) return null;
  const h = Math.min(23, parseInt(m[1], 10));
  const min = Math.min(59, parseInt(m[2], 10));
  return `${String(h).padStart(2, '0')}:${String(min).padStart(2, '0')}`;
}

function clientConfirmed(text) {
  return /\b(sim|confirmo|confirmar|pode ser|isso mesmo|isso|ok|fechado|perfeito|pode marcar|pode agendar)\b/i.test(
    text,
  );
}

function wantsScheduling(text) {
  return /agendar|marcar|hor[aá]rio|reservar|corte|barba/i.test(text);
}

function hasServiceHint(text, services) {
  if (resolveFromCatalog(text, services)) return true;
  return /corte|barba|servi/i.test(text);
}

function hasProfessionalHint(text, professionals) {
  if (resolveFromCatalog(text, professionals)) return true;
  return (professionals || []).some((p) => {
    const n = String(p.name ?? '').trim();
    return n.length > 2 && text.toLowerCase().includes(n.toLowerCase());
  });
}

const out = parseAgentPayload(root.output ?? root.json ?? root);

const defaultCustomer = String(
  defaults.customer_id ?? $env.QA_DEFAULT_CUSTOMER_ID ?? '00000000-0000-4000-8000-000000004031',
).trim();

const customer_id =
  (okUuid(out.customer_id) ? out.customer_id.trim() : null) ??
  inbound.customer_id ??
  parent.enrichment?.customer_id ??
  parent.core_response?.customerId ??
  defaultCustomer;

/** Nunca preenche profissional/servico default — evita agendar Fred/corte sem escolha do cliente. */
let professional_id =
  out.professional_id ??
  out.professional ??
  resolveFromCatalog(out.professional_name, catalog.professionals ?? []);
if (!okUuid(professional_id)) {
  professional_id = resolveFromCatalog(sessionText, catalog.professionals ?? []);
  if (professional_id && !hasProfessionalHint(sessionText, catalog.professionals)) {
    professional_id = null;
  }
}

let service_id =
  out.service_id ?? out.service ?? resolveFromCatalog(out.service_name, catalog.services ?? []);
if (!okUuid(service_id)) {
  service_id = resolveFromCatalog(sessionText, catalog.services ?? []);
  if (service_id && !hasServiceHint(sessionText, catalog.services)) {
    service_id = null;
  }
}

const appointment_date = resolveAppointmentDate(
  out.appointment_date ?? out.date ?? null,
  sessionText,
);

let appointment_time = out.appointment_time ?? out.time ?? parseTimeHint(sessionText);
if (appointment_time && !/^\d{2}:\d{2}$/.test(String(appointment_time))) {
  appointment_time = parseTimeHint(String(appointment_time));
}

const hasDate = isIsoDate(appointment_date);
const hasTime = /^\d{2}:\d{2}$/.test(String(appointment_time ?? ''));
const hasPro = okUuid(professional_id);
const hasSvc = okUuid(service_id);

let ready_to_book = out.ready_to_book === true || out.explicit_confirmation === true;
if (ready_to_book && !clientConfirmed(lastMessage) && !clientConfirmed(sessionText.slice(-120))) {
  ready_to_book = false;
}
if (ready_to_book && !(hasPro && hasSvc && hasDate && hasTime)) {
  ready_to_book = false;
}

let intent = String(out.intent ?? '').trim();

if (!intent) {
  if (/^(oi|ol[aá]|bom dia|boa tarde|boa noite|tudo bem)\b/i.test(lastMessage) && !wantsScheduling(sessionText)) {
    intent = 'informacao_empresa';
  } else if (ready_to_book && hasPro && hasSvc && hasDate && hasTime) {
    intent = 'criar_agendamento';
  } else if (wantsScheduling(sessionText)) {
    intent = 'coletar_agendamento';
  } else {
    intent = 'informacao_empresa';
  }
}

if (intent === 'criar_agendamento' && !ready_to_book) {
  intent = 'coletar_agendamento';
}

if (intent === 'criar_agendamento' && !(hasPro && hasSvc && hasDate && hasTime)) {
  intent = 'coletar_agendamento';
  ready_to_book = false;
}

let response_text = String(
  out.response_text ?? 'Ola! Como posso ajudar voce hoje?',
);

if (/agendamento (foi )?(confirmado|realizado|marcado)/i.test(response_text) && !ready_to_book) {
  response_text = response_text.replace(
    /agendamento (foi )?(confirmado|realizado|marcado)[^.!?]*/gi,
    'vamos continuar seu agendamento',
  );
}

if (/autentica|authorization|unauthorized|401|403/i.test(response_text)) {
  response_text =
    'Ola! Para agendar, me conta qual servico voce prefere e com qual profissional gostaria de ser atendido.';
}

const appointment_payload =
  out.appointment_payload && typeof out.appointment_payload === 'object'
    ? out.appointment_payload
    : {};

return [
  {
    json: {
      intent,
      ready_to_book,
      professional_id: hasPro ? professional_id : null,
      service_id: hasSvc ? service_id : null,
      appointment_date: hasDate ? appointment_date : null,
      appointment_time: hasTime ? appointment_time : null,
      customer_id,
      response_text,
      appointment_payload,
      inbound,
      session_text: sessionText,
    },
  },
];

/** Preserva payload WF01 + contexto multi-mensagem da sessão WhatsApp. */
const t = $input.first().json ?? {};
const enrichment = t.enrichment ?? {};
const normalized = t.normalized ?? {};
const core = t.core_response ?? {};
const conv = enrichment.conversation_context ?? t.conversation_context ?? {};

const sessionText = String(
  conv.session_text ?? conv.sessionText ?? normalized.text ?? '',
).trim();
const lastMessage = String(normalized.text ?? '').trim();

return [
  {
    json: {
      ...t,
      enrichment,
      normalized,
      core_response: core,
      conversation_context: conv,
      inbound: {
        phone: normalized.phone ?? null,
        message: lastMessage,
        session_text: sessionText || lastMessage,
        recent_messages: Array.isArray(conv.recent_messages) ? conv.recent_messages : [],
        push_name: normalized.push_name ?? null,
        customer_name: normalized.push_name ?? normalized.name ?? null,
        customer_id: enrichment.customer_id ?? core.customerId ?? null,
        tenant_id: enrichment.tenant_id ?? core.tenantId ?? null,
        message_id: enrichment.message_id ?? core.messageId ?? null,
        scheduling_draft:
          conv.scheduling_draft && typeof conv.scheduling_draft === 'object'
            ? conv.scheduling_draft
            : {},
      },
    },
  },
];

/** Monta contexto limpo para o agente (sem vazar erros HTTP 401/403 ao cliente). */
const prep = $('Preparar contexto inbound').first().json ?? {};
const inbound = prep.inbound ?? {};

function unwrapList(payload) {
  if (!payload || typeof payload !== 'object') return [];
  if (Array.isArray(payload)) return payload;
  if (Array.isArray(payload.data)) return payload.data;
  if (Array.isArray(payload.items)) return payload.items;
  return [];
}

function isHttpErrorShape(o) {
  if (!o || typeof o !== 'object') return false;
  const msg = String(o.message ?? o.error ?? '').toLowerCase();
  const status = o.statusCode ?? o.status;
  return (
    status === 401 ||
    status === 403 ||
    msg.includes('unauthorized') ||
    msg.includes('authorization failed') ||
    msg.includes('forbidden')
  );
}

function safeApiSlice(nodeName) {
  try {
    const row = $(nodeName).first().json;
    if (!row || isHttpErrorShape(row)) return { ok: false, data: [] };
    return { ok: true, data: unwrapList(row) };
  } catch (_) {
    return { ok: false, data: [] };
  }
}

function safeApiOverview(nodeName) {
  try {
    const row = $(nodeName).first().json;
    if (!row || isHttpErrorShape(row) || !row.customer) return { ok: false, data: null };
    return { ok: true, data: row };
  } catch (_) {
    return { ok: false, data: null };
  }
}

function pickAppointmentSummary(row) {
  if (!row) return null;
  return {
    id: row.id,
    status: row.status,
    starts_at: row.starts_at,
    ends_at: row.ends_at,
    service_name: row.service_name,
    professional_name: row.professional_name,
  };
}

function buildCustomerMemory(overview) {
  if (!overview?.ok || !overview.data) {
    return {
      registered_name: null,
      is_vip: false,
      last_appointment: null,
      next_appointment: null,
      recent_services: [],
      profile_available: false,
    };
  }

  const data = overview.data;
  const customer = data.customer ?? {};
  const appts = Array.isArray(data.appointments) ? data.appointments : [];
  const nowMs = Date.now();

  const sorted = [...appts].sort(
    (a, b) => new Date(b.starts_at).getTime() - new Date(a.starts_at).getTime(),
  );

  const past = sorted.filter((a) => new Date(a.starts_at).getTime() < nowMs);
  const future = sorted
    .filter((a) => new Date(a.starts_at).getTime() >= nowMs)
    .sort((a, b) => new Date(a.starts_at).getTime() - new Date(b.starts_at).getTime());

  const lastCompleted =
    past.find((a) => a.status === 'completed') ??
    past.find((a) => ['completed', 'confirmed', 'scheduled', 'no_show'].includes(String(a.status))) ??
    past[0] ??
    null;

  return {
    registered_name: customer.name ?? null,
    is_vip: Boolean(customer.is_vip),
    last_appointment: pickAppointmentSummary(lastCompleted),
    next_appointment: pickAppointmentSummary(future[0] ?? null),
    recent_services: Array.isArray(data.recent_services) ? data.recent_services : [],
    last_interaction_at: customer.last_interaction_at ?? null,
    profile_available: true,
  };
}

const services = safeApiSlice('Catalogo servicos Core API');
const professionals = safeApiSlice('Catalogo profissionais Core API');
const appointments = safeApiSlice('Contexto agenda Core API');
const overview = safeApiOverview('Perfil cliente Core API');

const catalog = {
  services: services.data.map((s) => ({
    id: s.id,
    name: s.name ?? s.title,
    duration_minutes: s.duration_minutes ?? s.durationMinutes,
  })),
  professionals: professionals.data.map((p) => ({
    id: p.id,
    name: p.name ?? p.display_name ?? p.displayName,
  })),
  appointments_next_7d: appointments.data.slice(0, 30),
  api_errors: {
    services: !services.ok,
    professionals: !professionals.ok,
    appointments: !appointments.ok,
    customer_profile: !overview.ok,
  },
};

const customer_memory = buildCustomerMemory(overview);

const defaultProfessional = String(
  $env.QA_DEFAULT_PROFESSIONAL_ID || '00000000-0000-4000-8000-000000004012',
).trim();
const defaultService = String(
  $env.QA_DEFAULT_SERVICE_ID || '00000000-0000-4000-8000-000000004021',
).trim();

return [
  {
    json: {
      inbound,
      enrichment: prep.enrichment ?? {},
      normalized: prep.normalized ?? {},
      core_response: prep.core_response ?? {},
      catalog,
      customer_memory,
      defaults: {
        professional_id: defaultProfessional,
        service_id: defaultService,
        customer_id: String(
          $env.QA_DEFAULT_CUSTOMER_ID || '00000000-0000-4000-8000-000000004031',
        ).trim(),
      },
    },
  },
];

const j = $input.first().json ?? {};
const UUID_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const okUuid = (v) => typeof v === 'string' && UUID_RE.test(v.trim());
const dateOk = /^\d{4}-\d{2}-\d{2}$/.test(String(j.appointment_date ?? ''));
const timeOk = /^\d{2}:\d{2}$/.test(String(j.appointment_time ?? ''));

/** Cria agendamento na API somente com confirmacao explicita + dados completos (atendimento humanizado). */
const route =
  j.intent === 'criar_agendamento' &&
  j.ready_to_book === true &&
  okUuid(j.professional_id) &&
  okUuid(j.service_id) &&
  dateOk &&
  timeOk
    ? 'criar'
    : 'outbound';

return [{ json: { ...j, _route: route } }];

/** Une rota (intent/UUIDs) com resposta de /availability para os nos seguintes. */
const route = $('Rotear fluxo').first().json ?? {};
const avail = $input.first().json ?? {};
const raw =
  avail.slots ??
  avail.data?.slots ??
  avail.body?.slots ??
  [];
const slots = (Array.isArray(raw) ? raw : [])
  .map((s) => ({
    starts_at: s?.starts_at ?? s?.startsAt ?? null,
    ends_at: s?.ends_at ?? s?.endsAt ?? null,
  }))
  .filter((s) => s.starts_at && s.ends_at);

return [
  {
    json: {
      ...route,
      slots,
      availability: avail,
    },
  },
];

/** Monta POST /appointments — escolhe slot (preferência de horário se informada). */
const row = $input.first().json ?? {};
const slots = Array.isArray(row.slots) ? row.slots : [];

if (!slots.length) {
  return [
    {
      json: {
        ...row,
        appointment_payload: null,
        response_text:
          row.response_text ||
          'No momento nao temos horarios livres para essa data. Quer tentar outro dia?',
      },
    },
  ];
}

function pickSlot(list, preferred) {
  if (!preferred || !/^\d{2}:\d{2}$/.test(preferred)) return list[0];
  const [ph, pm] = preferred.split(':').map((x) => parseInt(x, 10));
  let best = list[0];
  let bestDiff = Number.MAX_SAFE_INTEGER;
  for (const s of list) {
    const d = new Date(s.starts_at);
    const diff = Math.abs(d.getUTCHours() * 60 + d.getUTCMinutes() - (ph * 60 + pm));
    if (diff < bestDiff) {
      bestDiff = diff;
      best = s;
    }
  }
  return best;
}

const slot = pickSlot(slots, row.appointment_time);
const execId = String($execution.id);
const payload = {
  customer_id: row.customer_id,
  professional_id: row.professional_id,
  service_id: row.service_id,
  starts_at: slot.starts_at,
  ends_at: slot.ends_at,
  source: 'whatsapp',
  explicit_confirmation: true,
  idempotency_key: `n8n-wf02-appt-${execId}`,
  notes: 'Agendamento via agente WhatsApp (WF02)',
};

return [{ json: { ...row, ...payload, appointment_payload: payload } }];
